// Parse Signals: extract structured data, freshness, and entity signals from HTML.
// String parsing + JSON.parse only. No URL class, no external libraries.

const src = $('Read from Google Sheets').item.json;
let html = typeof $json.data === 'string' ? $json.data : String($json.data || '');
if (!html || html.length < 500) {
  throw new Error('Fetch for ' + (src.page_url || 'row') + ' returned almost no HTML. The page may be blocked or JS-rendered.');
}

// --- helpers ---
function meta(nameOrProp) {
  const re = new RegExp('<meta[^>]+(?:name|property)=["\']' + nameOrProp + '["\'][^>]*>', 'i');
  const m = html.match(re);
  if (!m) return '';
  const c = m[0].match(/content=["']([^"']*)["']/i);
  return c ? c[1].trim() : '';
}
function firstTag(tag) {
  const m = html.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  return m ? m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
}

// --- JSON-LD extraction ---
const ldBlocks = [];
const ldRe = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
let m;
while ((m = ldRe.exec(html)) !== null) {
  try {
    const parsed = JSON.parse(m[1].trim());
    if (Array.isArray(parsed)) ldBlocks.push(...parsed);
    else if (parsed['@graph'] && Array.isArray(parsed['@graph'])) ldBlocks.push(...parsed['@graph']);
    else ldBlocks.push(parsed);
  } catch (e) { /* malformed block: note via count below */ }
}
function nodeTypes(n) {
  const t = n && n['@type'];
  if (!t) return [];
  return Array.isArray(t) ? t.map(String) : [String(t)];
}
const allTypes = [];
for (const n of ldBlocks) allTypes.push(...nodeTypes(n));

const ARTICLE_TYPES = ['Article', 'TechArticle', 'BlogPosting', 'NewsArticle'];
const articleNode = ldBlocks.find(n => nodeTypes(n).some(t => ARTICLE_TYPES.indexOf(t) >= 0)) || null;
const hasArticle = !!articleNode;
const hasFaq = allTypes.indexOf('FAQPage') >= 0;
const hasOrg = allTypes.indexOf('Organization') >= 0 ||
  (articleNode && articleNode.publisher && nodeTypes(articleNode.publisher).indexOf('Organization') >= 0);
const hasBreadcrumb = allTypes.indexOf('BreadcrumbList') >= 0;

// --- dates: schema first, meta fallback ---
const datePublished = (articleNode && String(articleNode.datePublished || '')) || meta('article:published_time') || '';
const dateModified = (articleNode && String(articleNode.dateModified || '')) || meta('article:modified_time') || '';

// --- author ---
let authorName = '';
if (articleNode && articleNode.author) {
  const a = Array.isArray(articleNode.author) ? articleNode.author[0] : articleNode.author;
  authorName = typeof a === 'string' ? a : String((a && a.name) || '');
}
if (!authorName) authorName = meta('author');

// --- page basics ---
const title = firstTag('title');
const h1 = firstTag('h1');
const description = meta('description') || meta('og:description');
const canonMatch = html.match(/<link[^>]+rel=["']canonical["'][^>]*>/i);
const canonical = canonMatch ? ((canonMatch[0].match(/href=["']([^"']*)["']/i) || [])[1] || '') : '';
const robots = meta('robots').toLowerCase();
const noindex = robots.indexOf('noindex') >= 0;

// --- query match + freshness ---
const q = String(src.target_query || '').toLowerCase();
const qWords = q.split(/[^a-z0-9]+/).filter(w => w.length > 3);
const tLower = (title + ' ' + h1).toLowerCase();
const matched = qWords.filter(w => tLower.indexOf(w) >= 0);
const titleMatchesQuery = qWords.length > 0 && matched.length / qWords.length >= 0.5;
const yearMatch = (title + ' ' + h1).match(/20(2[4-9]|3[0-9])/);
const freshnessYear = yearMatch ? yearMatch[0] : '';

// --- headers + visible text excerpt for the judge ---
const qHeaders = (html.match(/<h[23][^>]*>[^<]*\?/gi) || []).length;
let body = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ');
const coreM = body.match(/<(article|main)[^>]*>([\s\S]*?)<\/\1>/i);
let excerpt = (coreM ? coreM[2] : body)
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ').trim().slice(0, 1500);

const signals = {
  page_url: src.page_url, brand: src.brand || '', target_query: src.target_query || '',
  title: title, h1: h1, meta_description_present: !!description,
  schema_types: allTypes.join(', '), jsonld_block_count: ldBlocks.length,
  has_article_schema: hasArticle, has_faq_schema: hasFaq, has_org_schema: hasOrg,
  has_breadcrumb: hasBreadcrumb,
  date_published: datePublished, date_modified: dateModified,
  author_name: authorName, canonical_present: !!canonical, noindex: noindex,
  title_matches_query: titleMatchesQuery, freshness_year: freshnessYear,
  question_headers: qHeaders
};

const SYSTEM = 'You are a technical GEO auditor. You receive extracted machine-layer signals from a web page plus a short text excerpt. Do two things.\n\n' +
'1. ENTITY CONSISTENCY (score 0-100): Is the brand named and described consistently across title, H1, structured data, and the opening text? Does the machine layer (schema, metadata) describe the same entity and topic as the prose? Anchors: 90-100 brand named in title, H1, and schema with consistent description; 70-89 brand present but one surface (title, H1, or schema) omits or blurs it; 50-69 brand present in prose but weak or absent in the machine layer; below 50 the machine layer describes a different or generic entity. Quote the specific signals that drove your score.\n\n' +
'2. GAPS AND RECOMMENDED JSON-LD: Rank the top gaps by likely impact on AI citation (missing or incomplete schema, missing dates, stale or absent freshness signals, title/query mismatch, missing author or publisher). Then, if and only if schema gaps exist, generate ONE paste-ready JSON-LD block that fixes them.\n\n' +
'STRICT HONESTY RULE for the JSON-LD: it may only describe what the page verifiably contains based on the provided signals and excerpt. Use the real title, real dates, real author when present. Use the string [PLACEHOLDER: description] for any required value the page does not expose. NEVER invent ratings, reviews, FAQ questions the page does not contain, or dates. Only include FAQPage schema if question_headers indicates real Q&A content. If existing schema is already complete, return an empty string for recommended_jsonld.\n\n' +
'Return ONLY a JSON object, no markdown fences:\n' +
'{"entity_consistency": {"score": 0, "evidence": ["..."], "issues": ["..."]}, "top_gaps": [{"gap": "...", "impact": "high|medium|low"}], "recommended_jsonld": "..."}';

return {
  json: Object.assign({ page_id: String(src.page_id || '').trim() || 'row', signals: signals }, {
    payload: {
      model: 'gpt-4o-mini', temperature: 0, response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: 'EXTRACTED SIGNALS:\n' + JSON.stringify(signals, null, 2) + '\n\nOPENING TEXT EXCERPT:\n"""\n' + excerpt + '\n"""' }
      ]
    }
  })
};

// Parse & Score: deterministic technical score from the checklist + judge entity score.

const src = $('Extract Page Signals').item.json;
const s = src.signals;

let raw = '';
try { raw = $json.choices[0].message.content || ''; }
catch (e) { throw new Error('Unexpected API response for ' + src.page_id + ': ' + JSON.stringify($json).slice(0, 300)); }
let cleaned = raw.trim();
if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
let judged;
try { judged = JSON.parse(cleaned); }
catch (e) { throw new Error('Judge returned unparseable JSON for ' + src.page_id + '. First 300 chars: ' + cleaned.slice(0, 300)); }

function clamp(n) { const x = Number(n); return isFinite(x) ? Math.max(0, Math.min(100, Math.round(x))) : 0; }

// Deterministic technical checklist (100 points)
let tech = 0;
if (s.has_article_schema) tech += 20;
if (s.date_published) tech += 10;
if (s.date_modified) tech += 10;
if (s.author_name) tech += 10;
if (s.has_org_schema) tech += 10;
if (s.has_faq_schema) tech += 10;
if (s.canonical_present) tech += 5;
if (s.meta_description_present) tech += 5;
if (s.title_matches_query) tech += 10;
if (s.freshness_year) tech += 5;
if (!s.noindex) tech += 5;

const ec = judged.entity_consistency || {};
const entityScore = clamp(ec.score);
const auditScore = Math.round(tech * 0.6 + entityScore * 0.4);

const gaps = Array.isArray(judged.top_gaps) ? judged.top_gaps.slice(0, 5) : [];
const gapsFlat = gaps.map((g, i) => (i + 1) + '. [' + String(g.impact || 'n/a') + '] ' + String(g.gap || '').trim()).join(' | ');
const issuesFlat = Array.isArray(ec.issues) ? ec.issues.join('; ') : '';

let rec = String(judged.recommended_jsonld || '').trim();
if (rec.length > 45000) rec = rec.slice(0, 45000);

return { json: {
  run_date: new Date().toISOString().slice(0, 10),
  page_id: src.page_id,
  page_url: s.page_url,
  title: s.title,
  schema_types: s.schema_types,
  has_article_schema: s.has_article_schema,
  has_faq_schema: s.has_faq_schema,
  has_org_schema: s.has_org_schema,
  date_published: s.date_published,
  date_modified: s.date_modified,
  author_present: !!s.author_name,
  canonical_present: s.canonical_present,
  noindex: s.noindex,
  title_matches_query: s.title_matches_query,
  freshness_year: s.freshness_year,
  technical_score: tech,
  entity_score: entityScore,
  audit_score: auditScore,
  top_gaps: gapsFlat,
  recommended_jsonld: rec,
  issues: issuesFlat
} };
